-- Ante Imperium: overrides loaded after vanilla 00_defines.lua
-- Dates use AUC (ab urbe condita) years: AUC = 754 - BC year  (509 BC = 245 AUC)
-- Region id lists live in zz_ante_regions.lua (generated by tools/newmap.py).

NDefines.NGame.START_DATE = "245.1.1.12"
NDefines.NGame.END_DATE = "700.1.1.1"
NDefines.NGame.TENSION_TIME_SCALE_START_DATE = "245.1.1.12"

-- the world tension clock moved to NDiplomacy in newer game versions
if NDefines.NDiplomacy then
	NDefines.NDiplomacy.TENSION_TIME_SCALE_START_DATE = "245.1.1.12"
end

-- vanilla names a country tag here ("HAI") that does not exist in this mod
NDefines.NGame.HANDS_OFF_START_TAG = "ROM"

-- Day and night: where Greenwich lies on THIS map (vanilla: column 2793 of 5632) and how much of the
-- globe the map misses in the south (vanilla 0.17). Our map is a 2.4x zoom of the vanilla columns
-- 2530.. and rows 0..1280: Greenwich is column (2793 - 2530) * 2.4 = 631.
-- The map SHADER has the same numbers compiled in - tools/daynight.py patches a copy of it.
if NDefines_Graphics and NDefines_Graphics.NGraphics then
	NDefines_Graphics.NGraphics.GMT_OFFSET = 631
	NDefines_Graphics.NGraphics.SOUTH_POLE_OFFSET = 0.455
	NDefines_Graphics.NGraphics.NORTH_POLE_OFFSET = 0.93

	-- The engine fades every country colour before it draws it (vanilla: saturation x0.6, brightness x0.8).
	-- With a palette of earth tones that leaves little more than grey: show the colours of colors.txt as written.
	NDefines_Graphics.NGraphics.COUNTRY_COLOR_SATURATION_MODIFIER = 1.0
	NDefines_Graphics.NGraphics.COUNTRY_COLOR_BRIGHTNESS_MODIFIER = 0.9
end

-- Performance: this world has ~215 AI countries at once (the base game ~70-90 in 1936), but no armies,
-- navies or air forces yet. These AI routines run for every country and have nothing to do in 509 BC,
-- so run them less often (base game values in brackets). Revisit when units/navies exist.
NDefines.NAI.AI_UPDATE_ROLES_FREQUENCY_HOURS = 168        -- (48)
NDefines.NAI.AI_NAVAL_GOALS_UPDATE_FREQUENCY_DAYS = 30    -- (7) every country logs 7 duplicate naval goals
NDefines.NAI.RESEARCH_DAYS_BETWEEN_WEIGHT_UPDATE = 14     -- (7)
NDefines.NAI.EQUIPMENT_MARKET_UPDATE_FREQUENCY_DAYS = 30  -- (11)
NDefines.NAI.DAYS_BETWEEN_CHECK_BEST_TEMPLATE = 30        -- (7)
NDefines.NAI.DAYS_BETWEEN_CHECK_BEST_EQUIPMENT = 30       -- (7)
NDefines.NAI.DAYS_BETWEEN_AIR_PRIORITIES_UPDATE = 14      -- (4)
NDefines.NAI.AIFC_UPDATE_FREQUENCY_DAYS = 10              -- (5)
NDefines.NAI.RAIDS_CREATE_FREQUENCY_DAYS = 30             -- (7)
NDefines.NGame.TRADE_ROUTE_RECALCULATE_FREQUENCY_DAYS = 90 -- (45)

-- Ancient tech tree (tools/tech.py): rows are 245..280 AUC (round 21; before: 245..365, 15-100 years between a tech
-- and the next while one tech took half a year). One tech point = 270 days of research (vanilla 110): the 66 techs
-- take 30-40 years at 2-3 research slots, about the length of the tree. Each year ahead adds 10% (vanilla 200%):
-- a row early (~3 years) costs a third more, ten years early double.
NDefines.NTechnology.BASE_TECH_COST = 270                 -- (110)
NDefines.NTechnology.BASE_YEAR_AHEAD_PENALTY_FACTOR = 0.10 -- (2)
